let _rank: Map<string, number> | null = null;
/** word → frequency rank (0 = most common). Absent words return Infinity. */
export function freqRankEn(word: string): number {
  if (!_rank) {
    _rank = new Map();
    for (let i = 0; i < FREQ_EN_LIST.length; i++) _rank.set(FREQ_EN_LIST[i]!, i);
  }
  const r = _rank.get(word.toLowerCase());
  return r === undefined ? Infinity : r;
}

// First-character buckets, built once. Scanning the whole 10k list per
// misspelled word is too slow on the hot path (a 500-word prompt with a small
// base dictionary flags many words). People almost never mistype the FIRST
// character of a word, so restricting frequency candidates to the same initial
// letter cuts the scan ~26× with negligible loss of recall — and the ranking
// already prefers same-first-letter anyway.
let _byFirst: Map<string, readonly string[]> | null = null;
/** Frequency-ordered candidate words that start with `ch` (a single char). */
export function freqCandidatesEn(ch: string): readonly string[] {
  if (!_byFirst) {
    _byFirst = new Map();
    for (const w of FREQ_EN_LIST) {
      const k = w[0]!;
      const arr = _byFirst.get(k) as string[] | undefined;
      if (arr) arr.push(w);
      else _byFirst.set(k, [w]);
    }
  }
  return _byFirst.get(ch.toLowerCase()) ?? [];
}
